"""Applies FormFlow's Android settings to the folder generated by
`flutter create --platforms android .` (camera permission, TTS query,
minimum SDK 24, app label). Safe to run more than once."""
import pathlib, re

root = pathlib.Path(__file__).resolve().parent.parent / "android"
manifest = root / "app" / "src" / "main" / "AndroidManifest.xml"
m = manifest.read_text()
perms = (
    '    <uses-permission android:name="android.permission.CAMERA" />\n'
    '    <uses-feature android:name="android.hardware.camera" android:required="false" />\n'
)
if "android.permission.CAMERA" not in m:
    m = re.sub(r"(<manifest[^>]*>\n)", r"\1" + perms, m, count=1)
if "TTS_SERVICE" not in m:
    tts = '        <intent>\n            <action android:name="android.intent.action.TTS_SERVICE" />\n        </intent>\n'
    if "<queries>" in m:
        m = m.replace("<queries>\n", "<queries>\n" + tts, 1)
    else:
        m = m.replace("</manifest>", "    <queries>\n" + tts + "    </queries>\n</manifest>")
m = re.sub(r'android:label="[^"]*"', 'android:label="FormFlow"', m, count=1)
manifest.write_text(m)

for name in ["build.gradle.kts", "build.gradle"]:
    g = root / "app" / name
    if g.exists():
        s = g.read_text()
        s = s.replace("minSdk = flutter.minSdkVersion", "minSdk = 24")
        s = s.replace("minSdkVersion flutter.minSdkVersion", "minSdkVersion 24")
        # Keep the APK light: ship only ML Kit's lite pose model (the app
        # always uses PoseDetectionModel.base); drops ~6.4 MB.
        marker = "pose_landmark_detector_full"
        if marker not in s:
            pattern = ("!.svn:!.git:!.ds_store:!*.scc:.*:!CVS:!thumbs.db:!picasa.ini:!*~:"
                       "!pose_landmark_detector_full_f16_inf.tflite")
            if name.endswith(".kts"):
                block = '    androidResources {\n        ignoreAssetsPattern = "%s"\n    }\n' % pattern
            else:
                block = '    aaptOptions {\n        ignoreAssetsPattern "%s"\n    }\n' % pattern
            s = re.sub(r"(android \{\n)", r"\1" + block.replace("\\", "\\\\"), s, count=1)
        g.write_text(s)
        print("patched", g)
print("patched", manifest)
